-- 55 Dragon's Hoard: carries the lantern and flickers the torch. The
-- glints are the engine's: every piece's material has a `specular`, its
-- normal map's alpha says what is metal, and the lights do the rest.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/55-dragons-hoard.scene"
local captions = true
local lantern, glow, torch, status
local t = 0
local follow = false
local last_x, last_y
local lx, ly = 0, 60

function init(entity)
    lantern = Entity.find_by_name("Lantern")
    glow = Entity.find_by_name("LanternGlow")
    torch = Entity.find_by_name("Torch")
    status = Entity.find_by_name("Status")
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    t = t + dt
    local mx, my = Input.get_mouse_world_position()
    if last_x and (math.abs(mx - last_x) + math.abs(my - last_y)) > 1 then follow = true end
    last_x, last_y = mx, my
    local tx, ty
    if follow then
        tx, ty = mx, my
    else
        -- Until the mouse moves, the lantern sways over the hoard by itself.
        tx, ty = math.sin(t * 0.45) * 420, -10 + math.sin(t * 0.9) * 90
    end
    -- Carried: it trails the hand a little and swings.
    lx = lx + (tx - lx) * math.min(1, dt * 6)
    ly = ly + (ty - ly) * math.min(1, dt * 6)
    local swing = math.sin(t * 3.1) * 4
    if lantern then Transform.set_position(lantern, lx + swing, ly) end
    if glow then Transform.set_position(glow, lx + swing, ly) end
    if torch then
        Lighting.set_intensity(torch, 0.8 + 0.15 * math.sin(t * 13) + 0.1 * math.sin(t * 29 + 1.3))
    end
    if status then UI.set_text(status, follow and "lantern in hand" or "move the mouse to carry the lantern") end
end
